import{_ as e,H as i,f as t,i as s}from"./chunks/framework.BH2BK_3i.js";const S=JSON.parse('{"title":"第四封信-0+0+0=0","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第四封信-0+0+0=0.md","filePath":"去无方向的信/第四封信-0+0+0=0.md","lastUpdated":1795542896000}'),a={name:"去无方向的信/第四封信-0+0+0=0.md"};function l(n,p,E,B,o,r){return i(),t("div",null,[...p[0]||(p[0]=[s('<h1 id="第四封信-0-0-0-0" tabindex="-1">第四封信-0+0+0=0 <a class="header-anchor" href="#第四封信-0-0-0-0" aria-label="Permalink to &quot;第四封信-0+0+0=0&quot;">​</a></h1><p>生生：</p><p>你好哇。</p><p>上次，咱们暴力限定了一下光圈、快门和 ISO 的档位，最终得到了六大档光圈、六大档快门和六大档 ISO。</p><p>我之所以管他们叫“大档”，是因为这是我从机械相机上移植过来的概念。</p><p>以前的机械相机不像现在的数码相机精度那么高，他们没有那么多档位，他们只是看上去复杂，但用起来其实很简单，而现在的数码相机，看上去简单，但用起来真的好艰难啊！我们可以先来看一眼那时候的相机：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-0%2B0%2B0%3D0/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-0%2B0%2B0%3D0/1.png" alt=""></a></p><ul><li>防杠声明：NIKON FE2 不是绝对意义上的机械相机，放这张图只是因为我喜欢，且我所需要的信息展示完整</li></ul><p>这么漂亮的相机，你可多看两眼吧，正好自己找一下光圈、快门和 ISO 都在哪儿，然后看看他们各自的档位。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-0%2B0%2B0%3D0/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-0%2B0%2B0%3D0/2.png" alt=""></a></p><p>单看光圈，数字越小，光圈越大；光圈越大，相机里的进光量越多；进光量越多，照片儿就会越亮。</p><p>单看快门，数字越小，快门速度越慢（因为是 1/n 秒，所以 n 越大，数值越小）；快门速度越慢，感光元件受光时间越长；受光时间越长，照片儿就会越亮。</p><p>单看 ISO，数字越大，感光度越高；感光度越高，感光元件的感光能力越强；感光能力越强，照片儿就会越亮。</p><p>反之亦然，然后咱们继续。</p><p>单看标粗的这六大档光圈，每相邻的两档之间，相差一档曝光，比如：F16 比 F11 小一档曝光。</p><p>单看标粗的这六大档快门，每相邻的两档之间，相差一档曝光，比如：1/250s 比 1/125s 小一档曝光。</p><p>单看标粗的这六大档 ISO，每相邻的两档之间，相差一档曝光，比如：800 比 1600 小一档曝光。</p><p>而“一档曝光”，我们可以叫它“1 eV”。</p><p>之前说过，三个参数组合起来就可以鼓捣出来一张照片儿，好，现在有这么一张照片儿：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-0%2B0%2B0%3D0/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-0%2B0%2B0%3D0/3.png" alt=""></a></p><p>这张照片儿的参数是：[1/125s F8 ISO200]</p><p>这意味着我用这组参数，在这个环境下，就可以拍出一张正常亮度的照片儿。如果我增大光圈，或放慢快门速度，或提高 ISO，那这张照片儿就会比现在更亮；而如果我减小光圈，或加快快门速度，或降低 ISO，那这张照片儿就会比现在更暗。</p><p>注意，虽然，这张照片儿的参数是：[1/125s F8 ISO200]</p><p>但这并不意味着，如果我想拍出这个亮度，我只能用 [1/125s F8 ISO200] 这组参数。</p><ul><li><p>我还可以用</p></li><li><p>如 [1/125s F5.6 ISO100]</p></li><li><p>或 [1/125s F11 ISO400]</p></li><li><p>或 [1/125s F16 ISO800]</p></li><li><p>这是保证快门速度不变，只动光圈和 ISO。</p></li><li><p>我还可以用</p></li><li><p>如 [1/60s F8 ISO100]</p></li><li><p>或 [1/250s F8 ISO400]</p></li><li><p>或 [1/500s F8 ISO800]</p></li><li><p>这是保证光圈大小不变，只动快门和 ISO。</p></li><li><p>我还可以用</p></li><li><p>如 [1/250s F5.6 ISO200]</p></li><li><p>或 [1/500s F4 ISO200]</p></li><li><p>或 [1/1000s F2.8 ISO200]</p></li><li><p>这是保证感光度不变，只动快门和光圈。</p></li><li><p>…</p></li><li><p>甚至三个参数都有所变化也没问题</p></li></ul><p>如果我们把标准曝光值暂且定为“0”，标准曝光值就是能拍出正常亮度的照片儿的意思，那标准的曝光公式基本可以理解为是“0+0+0=0”：等号前面的三个“0”分别是快门、光圈和 ISO，等号后面的“0”代表标准曝光值。</p><p>如果正常的曝光参数原本是 [0 0 0]，但现在我需要加快一档快门速度，于是，从曝光的角度来说，就变成了 “-1 + 0 + 0 = -1”，这意味着受快门速度影响，曝光减小了一档 (-1 eV)，所以为了把减小的那一档曝光补回来：</p><p>我们要不然就增大一档光圈，变成 [-1 +1 0]；要不然就增大一档 ISO，变成 [-1 0 +1]；或者减小一档光圈，但增大两档 ISO，变成 [-1 -1 +2]；甚至可以增大四档光圈，但减小三档 ISO，变成 [-1 +4 -3]。</p><p>总之，就是要变成三个参数的档位加起来归零的状态。</p><p>所以现在问题就来了，如果这么多种组合都可以拍出同样的曝光效果，那是不是随便选一组就可以哐哐拍了呢？就像我上次说过的，随便选出一档光圈，随便选出一档快门，再随便选出一档 ISO，只要保证他们组合在一起曝光正常就可以了，不是么？</p><p>不是。</p><p>对于上面那张照片儿， [1/125s F8 ISO200] 和 [1/15s F16 ISO100] 的曝光效果是一样的，也就是说，用这两组参数可以拍出两张曝光完全一样的照片儿。但是，我只能选前者，不能选后者。</p><p>[1/125s F8 ISO200] 和 [1/250s F8 ISO400] 的曝光效果是一样的，我拍的时候选了前者，但现在如果让我再重拍这张照片儿，我会选后者。</p><p>所以，就又回到了那个问题：真的是随便选么？如果不是，怎么选？怎么选是对的？怎么选才是最好的？</p><p>咱们之后有时间再继续聊。</p>',35)])])}const g=e(a,[["render",l]]);export{S as __pageData,g as default};
